Encode in one pass into a single String, no per-segment replace allocations and no intermediate Vec:
fn encode_path(path: &[RestorationKey]) -> String {
    let mut out = String::new();
    for (index, segment) in path.iter().enumerate() {
        if index > 0 {
            out.push('/');
        }
        for ch in segment.as_str().chars() {
            match ch {
                '~' => out.push_str("~0"),
                '/' => out.push_str("~1"),
                _ => out.push(ch),
            }
        }
    }
    out
}
